40	const uint64_t INT4_NUMS_IN_INT32 = 8;
41	
42	void TensorPreProcess(const aclTensorList *&tensorListKey, const aclTensorList *&tensorListValue)
43	{
44	    if (tensorListKey == nullptr) {
45	        OP_LOGD("TensorListKey is nullptr,TensorPreProcess exit.");
46	        return;
47	    }
48	    if (tensorListValue == nullptr) {
49	        OP_LOGD("tensorListValue is nullptr,TensorPreProcess exit.");
50	        return;
51	    }
52	    if ((*tensorListKey)[0]->GetDataType() != DataType::DT_INT32) {
53	        OP_LOGD("The conversion of kv's from OriginalShape is completed.");
54	        return;
55	    }
56	    if ((*tensorListValue)[0]->GetDataType() != DataType::DT_INT32) {
57	        OP_LOGD("The conversion of kv's from OriginalShape is completed.");
58	        return;
59	    }
60	    auto tempKey = const_cast<aclTensorList *>(tensorListKey);
61	    for (uint64_t i = 0; i < tempKey->Size(); i++) {
62	        if ((*tempKey)[i] != nullptr) {
63	            op::Shape viewShape = (*tempKey)[i]->GetViewShape();
64	            auto viewShapeDim = viewShape.GetDimNum();
65	            if (viewShapeDim >= 1) {
66	                viewShape[viewShapeDim - 1] = viewShape[viewShapeDim - 1] * INT4_NUMS_IN_INT32;
67	            }
68	            (*tempKey)[i]->SetViewShape(viewShape);
69	            (*tempKey)[i]->SetDataType(DataType::DT_INT4);
70	        }
71	    }
72	
73	    auto tempValue = const_cast<aclTensorList *>(tensorListValue);
74	    for (uint64_t i = 0; i < tempValue->Size(); i++) {
75	        if ((*tempValue)[i] != nullptr) {
76	            op::Shape viewShape = (*tempValue)[i]->GetViewShape();
77	            auto viewShapeDim = viewShape.GetDimNum();
78	            if (viewShapeDim >= 1) {
79	                viewShape[viewShapeDim - 1] = viewShape[viewShapeDim - 1] * INT4_NUMS_IN_INT32;
80	            }
81	            (*tempValue)[i]->SetViewShape(viewShape);
82	            (*tempValue)[i]->SetDataType(DataType::DT_INT4);
83	        }
84	    }
85	
86	    OP_LOGD("The conversion of kv from int32 to int4 is completed.");
87	}
