89	void PrefixTensorPreProcess(const aclTensor *&tensorKey, const aclTensor *&tensorValue)
90	{
91	    if (tensorKey == nullptr) {
92	        OP_LOGD("TensorListKey is nullptr,TensorPreProcess exit.");
93	        return;
94	    }
95	    if (tensorValue == nullptr) {
96	        OP_LOGD("tensorListValue is nullptr,TensorPreProcess exit..");
97	        return;
98	    }
99	    if (tensorKey->GetDataType() != DataType::DT_INT32) {
100	        OP_LOGD("The conversion of kvPrefix's from OriginalShape is completed.");
101	        return;
102	    }
103	    if (tensorValue->GetDataType() != DataType::DT_INT32) {
104	        OP_LOGD("The conversion of kvPrefix's from OriginalShape is completed.");
105	        return;
106	    }
107	    auto tempKey = const_cast<aclTensor *>(tensorKey);
108	    op::Shape viewKeyShape = tempKey->GetViewShape();
109	    auto viewKeyShapeDim = viewKeyShape.GetDimNum();
110	    viewKeyShape[viewKeyShapeDim - 1] = viewKeyShape[viewKeyShapeDim - 1] * INT4_NUMS_IN_INT32;
111	    tempKey->SetViewShape(viewKeyShape);
112	    tempKey->SetDataType(DataType::DT_INT4);
113	
114	    auto tempValue = const_cast<aclTensor *>(tensorValue);
115	    op::Shape viewValueShape = tempValue->GetViewShape();
116	    auto viewValueShapeDim = viewValueShape.GetDimNum();
117	    viewValueShape[viewValueShapeDim - 1] = viewValueShape[viewValueShapeDim - 1] * INT4_NUMS_IN_INT32;
118	    tempValue->SetViewShape(viewValueShape);
119	    tempValue->SetDataType(DataType::DT_INT4);
120	
121	    OP_LOGD("The conversion of kvPrefix from int32 to int4 is completed.");
122	}
