124	aclnnStatus FakeArray(const aclIntArray *inArray, aclTensor *&outTensor)
125	{
126	    OP_LOGD("start fake tensor");
127	    if (inArray != nullptr) {
128	        OP_LOGD("input array is not nullptr");
129	        int64_t size = static_cast<int64_t>(inArray->Size());
130	        std::vector<int64_t> shape = {size};
131	        outTensor = aclCreateTensor(shape.data(),
132	                                    shape.size(),
133	                                    aclDataType::ACL_INT64,
134	                                    nullptr,
135	                                    0,
136	                                    ACL_FORMAT_ND,
137	                                    shape.data(),
138	                                    shape.size(),
139	                                    nullptr);
140	        if (outTensor == nullptr) {
141	            OP_LOGE(ACLNN_ERR_INNER_NULLPTR, "Try alloc tensor failed");
142	            return ACLNN_ERR_INNER_NULLPTR;
143	        }
144	    }
145	    OP_LOGD("end fake tensor");
146	    return ACLNN_SUCCESS;
