149	void AiInfraFusedInferAttentionSinkProcessSoftmaxLse(bool softmaxLseFlag,
150	                                                     const aclTensor *softmaxLse,
151	                                                     const aclTensor *tempTensor,
152	                                                     const aclTensor *&placeHolder)
153	{
154	    if (softmaxLseFlag == false) {
155	        std::vector<int64_t> shape = {0};
156	        int64_t addr = 0xff;
157	        tempTensor = aclCreateTensor(shape.data(),
158	                                     shape.size(),
159	                                     aclDataType::ACL_FLOAT,
160	                                     shape.data(),
161	                                     0,
162	                                     ACL_FORMAT_ND,
163	                                     shape.data(),
164	                                     shape.size(),
165	                                     static_cast<void *>(&addr));
166	        placeHolder = tempTensor;
167	    } else {
168	        placeHolder = softmaxLse;
169	    }
170	}
