172	// CreateView 保留非连续 tensor 的 stride 信息
173	static const aclTensor *CalcNoContiguous(const aclTensor *input, aclOpExecutor *executor)
174	{
175	    if (input == nullptr) {
176	        return input;
177	    }
178	    // CreateView 保留非连续 tensor 的 stride 信息
179	    // 这样底层算子可以正确处理非连续的访存模式
180	    aclTensor *newInput = executor->CreateView(input,
181	                                               input->GetViewShape(), // 视图形状
182	                                               input->GetStorageShape(), // 底层存储形状
183	                                               input->GetViewStrides(), // 步幅（非连续的关键信息）
184	                                               input->GetViewOffset() // 偏移量
185	    );
186	    CHECK_RET(newInput != nullptr, nullptr);
187	    return newInput;
188	}
