190	// 处理非连续 tensor，如果是非连续则使用 CreateView，否则按原样返回
191	static const aclTensor *ProcessTensorContiguous(
192	    const aclTensor *tensor,
193	    aclOpExecutor *executor,
194	    const char *tensorName)
195	{
196	    if (tensor == nullptr) {
197	        return nullptr;
198	    }
199	    if (!IsContiguous(tensor)) {
200	        return CalcNoContiguous(tensor, executor);
201	    } else {
202	        tensor = l0op::Contiguous(tensor, executor);
203	    }
204	    return tensor;
205	}
