207	static aclnnStatus ContiguousInput(const aclTensor *&query,
208	                                   const aclTensor *&attenMaskOptional,
209	                                   const aclTensor *&blockTableOptional,
210	                                   const aclTensor *&queryRopeOptional,
211	                                   const aclTensor *&keySinkOptional,
212	                                   const aclTensor *&keyRopeSinkOptional,
213	                                   const aclTensor *&valueSinkOptional,
214	                                   aclOpExecutor *executor)
215	{
216	    query = l0op::Contiguous(query, executor);
217	    CHECK_RET(query != nullptr, ACLNN_ERR_INNER_NULLPTR);
218	
219	    if (attenMaskOptional) {
220	        attenMaskOptional = l0op::Contiguous(attenMaskOptional, executor);
221	        CHECK_RET(attenMaskOptional != nullptr, ACLNN_ERR_INNER_NULLPTR);
222	    }
223	    if (blockTableOptional) {
224	        blockTableOptional = l0op::Contiguous(blockTableOptional, executor);
225	        CHECK_RET(blockTableOptional != nullptr, ACLNN_ERR_INNER_NULLPTR);
226	    }
227	    if (queryRopeOptional) {
228	        queryRopeOptional = l0op::Contiguous(queryRopeOptional, executor);
229	        CHECK_RET(queryRopeOptional != nullptr, ACLNN_ERR_INNER_NULLPTR);
230	    }
231	
232	    if (keySinkOptional) {
233	        keySinkOptional = l0op::Contiguous(keySinkOptional, executor);
234	        CHECK_RET(keySinkOptional != nullptr, ACLNN_ERR_INNER_NULLPTR);
235	    }
236	    if (keyRopeSinkOptional) {
237	        keyRopeSinkOptional = l0op::Contiguous(keyRopeSinkOptional, executor);
238	        CHECK_RET(keyRopeSinkOptional != nullptr, ACLNN_ERR_INNER_NULLPTR);
239	    }
240	    if (valueSinkOptional) {
241	        valueSinkOptional = l0op::Contiguous(valueSinkOptional, executor);
242	        CHECK_RET(valueSinkOptional != nullptr, ACLNN_ERR_INNER_NULLPTR);
243	    }
244	
245	    return ACLNN_SUCCESS;
246	}
