248	// 处理 TensorList 中所有 tensor 的连续性，返回新的 TensorList
249	static const aclTensorList *ProcessTensorListContiguous(const aclTensorList *tensorList,
250	                                                        aclOpExecutor *executor,
251	                                                        const char *tensorListName)
252	{
253	    if (tensorList == nullptr) {
254	        return nullptr;
255	    }
256	
257	    std::vector<const aclTensor *> processedTensorsTmp;
258	    uint64_t size = tensorList->Size();
259	
260	    for (uint64_t i = 0; i < size; i++) {
261	        const aclTensor *tensor = (*tensorList)[i];
262	        if (tensor == nullptr) {
263	            processedTensorsTmp.push_back(nullptr);
264	            // continue;
265	        }
266	
267	        // 处理单个 tensor 的连续性
268	        const aclTensor *processedTensor = ProcessTensorContiguous(tensor, executor, tensorListName);
269	
270	        CHECK_RET(processedTensor != nullptr, nullptr);
271	        processedTensorsTmp.push_back(processedTensor);
272	    }
273	
274	    // 创建新的 TensorList
275	    aclTensorList *processedTensors = executor->AllocTensorList(processedTensorsTmp.data(), processedTensorsTmp.size());
276	    CHECK_RET(processedTensors != nullptr, nullptr);
277	    return processedTensors;
278	}
