#include "ai_infra_fused_infer_attention_sink_tiling.h"
#include "error/ops_error.h"
#include "tiling/tiling_api.h"
#include "platform/platform_info.h"
#include "ai_infra_fused_infer_attention_sink_tiling_v3.h"
#include "register/device_op_impl_registry.h"

using namespace ge;
using namespace AscendC;
namespace optiling {
ge::graphStatus TilingAiInfraFusedInferAttentionSink(gert::TilingContext *context)
{
    if (context == nullptr) {
        OPS_LOG_E("AiInfraFusedInferAttentionSink", "tiling context is nullptr!");
        return ge::GRAPH_FAILED;
    }

    if (RouteToFia(context)) {
        return TilingAiInfraFusedInferAttentionSinkV3(context);
    }
    return ge::GRAPH_FAILED;
}

FIA_EXTERN_C ge::graphStatus DoOpTilingAiInfraFusedInferAttentionSink(gert::TilingContext *context)
{
    OPS_CHECK(context == nullptr,
              OPS_REPORT_VECTOR_INNER_ERR("AiInfraFusedInferAttentionSink", "Tiling context is null."),
              return ge::GRAPH_FAILED);

    auto platformInfoPtr = context->GetPlatformInfo();
    OPS_CHECK(platformInfoPtr == nullptr,
              OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "platformInfoPtr is null"),
              return ge::GRAPH_FAILED);

    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
    auto socShortName = ascendcPlatform.GetSocVersion();
    if (socShortName == platform_ascendc::SocVersion::ASCEND910_55) {
        return ge::GRAPH_FAILED;
    } else {
        return TilingAiInfraFusedInferAttentionSink(context);
    }
    return ge::GRAPH_SUCCESS;
}

extern "C" {
__attribute__((visibility("default"))) ge::graphStatus DeviceDoOpTilingAiInfraFusedInferAttentionSink
    (gert::TilingContext *context)
{
    return DoOpTilingAiInfraFusedInferAttentionSink(context);
}
}
DEVICE_IMPL_OP_OPTILING(AiInfraFusedInferAttentionSink)
    .Tiling(optiling::DeviceDoOpTilingAiInfraFusedInferAttentionSink);
} // namespace optiling

