24	// FIA新TilingKey, 18位编码, IFA原有TilingKey是17位, 新的TilingKey只是把最高位从1X->10X
25	// Gqa NoQuant PA dtype: Q=FP16 KV=FP16 OUT=FP16
26	REGISTER_TILING_DATA_CLASS(AiInfraFusedInferAttentionSink, AiInfraFusedInferAttentionSinkTilingData)
27	
28	constexpr size_t DIM_NZ = 5;
29	constexpr uint32_t NZ_D1_IDX = 2;
30	constexpr uint32_t NZ_D0_IDX = 4;
31	constexpr uint32_t TND_NTD_D_IDX = 2;
32	constexpr int64_t HEAD_DIM_192 = 192;
33	constexpr uint64_t DIM_NUM_3 = 3;
34	constexpr uint64_t DIM_NUM_4 = 4;
35	
36	FIA_EXTERN_C ge::graphStatus TilingAiInfraFusedInferAttentionSinkV3(gert::TilingContext *context)
37	{
38	    FiaTilingInfo fiaInfo;
39	    FiaInfoParser fiaInfoParser(context);
40	    if (fiaInfoParser.Parse(fiaInfo) != ge::GRAPH_SUCCESS) {
41	        return ge::GRAPH_FAILED;
42	    }
43	
44	    // Check函数只做校验，不能修改fiaInfo中的信息
45	    if (TilingCheck::Check(fiaInfo) != ge::GRAPH_SUCCESS) {
46	        return ge::GRAPH_FAILED;
47	    }
48	
49	    return FiaTilingRegistry::GetInstance().DoTilingImpl(context, &fiaInfo);
50	}
51	
52	bool GetPaValueD(gert::TilingContext *context, int64_t &valueD)
53	{
54	    auto attrs = context->GetAttrs();
55	    int64_t numHeads = static_cast<int64_t>(*attrs->GetAttrPointer<uint32_t>(ATTR_N_INDEX));
56	    int64_t numKvHeads = static_cast<int64_t>(*attrs->GetAttrPointer<uint32_t>(ATTR_NUM_KV_HEADS_INDEX));
57	    if (numKvHeads == 0) {
58	        numKvHeads = numHeads;
59	    }
60	    auto vStorageShape = context->GetInputShape(VALUE_INDEX)->GetShape();
61	    if (vStorageShape.GetDimNum() == DIM_BSH) {
62	        valueD = vStorageShape.GetDim(BSH_H_IDX) / numKvHeads; // BnBsH
63	    } else if (vStorageShape.GetDimNum() == DIM_BNSD_OR_BSND) {
64	        valueD = vStorageShape.GetDim(BNSD_D_IDX); // BnNBsD
65	    } else if (vStorageShape.GetDimNum() == DIM_NZ) {
66	        valueD = vStorageShape.GetDim(NZ_D1_IDX) * vStorageShape.GetDim(NZ_D0_IDX); // NZ: BnND1BsD0
67	    } else {
68	        return false;
69	    }
70	    return true;
71	}
72	
73	bool GetValueD(gert::TilingContext *context, int64_t &valueD)
74	{
75	    auto vShape = context->GetInputShape(VALUE_INDEX);
76	    if (vShape == nullptr) {
77	        return false;
78	    }
79	    auto vStorageShape = vShape->GetShape();
80	
81	    bool isPageAttention = context->GetOptionalInputShape(BLOCK_TABLE_INDEX) != nullptr;
82	    if (isPageAttention) {
83	        return GetPaValueD(context, valueD);
84	    }
85	
86	    auto attrs = context->GetAttrs();
87	    int64_t numHeads = static_cast<int64_t>(*attrs->GetAttrPointer<uint32_t>(ATTR_N_INDEX));
88	    int64_t numKvHeads = static_cast<int64_t>(*attrs->GetAttrPointer<uint32_t>(ATTR_NUM_KV_HEADS_INDEX));
89	    if (numKvHeads == 0) {
90	        numKvHeads = numHeads;
91	    }
92	    const std::string inputLayoutStr = std::string(context->GetAttrs()->GetAttrPointer<char>(ATTR_INPUT_LAYOUT_INDEX));
93	    if (inputLayoutStr == "BNSD_BSND" ||
94	        inputLayoutStr == "BSND_BNSD" ||
95	        inputLayoutStr == "BNSD_NBSD" ||
96	        inputLayoutStr == "BSND_NBSD" ||
97	        inputLayoutStr == "BNSD" ||
98	        inputLayoutStr == "BSND") {
99	        if (vStorageShape.GetDimNum() != DIM_BNSD_OR_BSND) {
100	            return false;
101	        }
102	        valueD = vStorageShape.GetDim(BNSD_D_IDX);
103	    } else if (inputLayoutStr == "BSH" ||
104	        inputLayoutStr == "BSH_NBSD" ||
105	        inputLayoutStr == "BSH_BNSD") {
106	        if (vStorageShape.GetDimNum() != DIM_BSH) {
107	            return false;
108	        }
109	        valueD = vStorageShape.GetDim(BSH_H_IDX) / numKvHeads;
110	    } else if (inputLayoutStr == "TND" ||
111	        inputLayoutStr == "NTD" ||
112	        inputLayoutStr == "TND_NTD" ||
113	        inputLayoutStr == "NTD_TND") {
114	        if (vStorageShape.GetDimNum() != DIM_TND) {
115	            return false;
116	        }
117	        valueD = vStorageShape.GetDim(TND_NTD_D_IDX);
118	    } else {
119	        return false;
120	    }
121	
122	    return true;
123	}
124	
125	bool GetQkvD(gert::TilingContext *context, int64_t &queryD, int64_t &queryRopeD, int64_t &valueD)
126	{
127	    auto qShape = context->GetInputShape(QUERY_INDEX);
128	    auto qRopeShape = context->GetOptionalInputShape(QUERY_ROPE_INDEX);
129	    if (qShape == nullptr) {
130	        return false;
131	    }
132	    auto qStorageShape = qShape->GetStorageShape();
133	
134	    auto attrs = context->GetAttrs();
135	    if (attrs == nullptr) {
136	        return false;
137	    }
138	
139	    int64_t numHeads = static_cast<int64_t>(*attrs->GetAttrPointer<uint32_t>(ATTR_N_INDEX));
140	    const std::string inputLayoutStr = std::string(context->GetAttrs()->GetAttrPointer<char>(ATTR_INPUT_LAYOUT_INDEX));
141	    if (inputLayoutStr == "BNSD_BSND" ||
142	        inputLayoutStr == "BSND_BNSD" ||
143	        inputLayoutStr == "BNSD_NBSD" ||
144	        inputLayoutStr == "BSND_NBSD" ||
145	        inputLayoutStr == "BNSD" ||
146	        inputLayoutStr == "BSND") {
147	        if (qStorageShape.GetDimNum() != DIM_BNSD_OR_BSND) {
148	            return false;
149	        }
150	        queryD = qStorageShape.GetDim(BNSD_D_IDX);
151	        if (qRopeShape != nullptr) {
152	            queryRopeD = qRopeShape->GetStorageShape().GetDim(BNSD_D_IDX);
153	        }
154	    } else if (inputLayoutStr == "BSH" ||
155	        inputLayoutStr == "BSH_NBSD" ||
156	        inputLayoutStr == "BSH_BNSD") {
157	        if (qStorageShape.GetDimNum() != DIM_BSH) {
158	            return false;
159	        }
160	        queryD = qStorageShape.GetDim(BSH_H_IDX) / numHeads;
161	        if (qRopeShape != nullptr) {
162	            queryRopeD = qRopeShape->GetStorageShape().GetDim(BSH_H_IDX) / numHeads;
163	        }
164	    } else if (inputLayoutStr == "TND" ||
165	        inputLayoutStr == "NTD" ||
166	        inputLayoutStr == "TND_NTD" ||
167	        inputLayoutStr == "NTD_TND") {
168	        if (qStorageShape.GetDimNum() != DIM_TND) {
169	            return false;
170	        }
171	        queryD = qStorageShape.GetDim(TND_NTD_D_IDX);
172	        if (qRopeShape != nullptr) {
173	            queryRopeD = qRopeShape->GetStorageShape().GetDim(TND_NTD_D_IDX);
174	        }
175	    } else {
176	        return false;
177	    }
178	
179	    return GetValueD(context, valueD);
180	}
181	
182	bool CheckGqaDSupport(gert::TilingContext *context)
183	{
184	    int64_t queryD = 0;
185	    int64_t queryRopeD = 0;
186	    int64_t valueD = 0;
187	    if (GetQkvD(context, queryD, queryRopeD, valueD) != true) {
188	        return false;
189	    }
190	
191	    // D的组合(128+0,128)(64+0,64)(128+64,128)(192+0,128)
192	    if ((queryD  == 128 && queryRopeD  == 0 && valueD == 128) || // 128: gqa qkvD
193	        (queryD  == 64 && queryRopeD  == 0 && valueD == 64) || // 64: gqa qkvD
194	        (queryD  == 128 && queryRopeD  == 64 && valueD == 128) || // 128: gqa qkvD, 64: mla ropeD
195	        (queryD  == 192 && queryRopeD  == 0 && valueD == 128)) { // 192: gqa qkD, 128: gqa valueD
196	        return true;
197	    }
198	
199	    return false;
200	}
201	
202	bool CheckGqaInputLayoutSupport(gert::TilingContext *context)
203	{
204	    const std::string inputLayoutStr = std::string(context->GetAttrs()->GetAttrPointer<char>(ATTR_INPUT_LAYOUT_INDEX));
205	    if (inputLayoutStr == "BNSD_BSND" ||
206	        inputLayoutStr == "BSND_BNSD" ||
207	        inputLayoutStr == "BNSD" ||
208	        inputLayoutStr == "BSND" ||
209	        inputLayoutStr == "BSH_BNSD" ||
210	        inputLayoutStr == "BSH" ||
211	        inputLayoutStr == "TND" ||
212	        inputLayoutStr == "NTD" ||
213	        inputLayoutStr == "NTD_TND") {
214	        return true;
215	    }
216	    return false;
217	}
218	
219	bool IsEmptyTensor(gert::TilingContext *context)
220	{
221	    auto qShape = context->GetInputShape(QUERY_INDEX);
222	    if ((qShape != nullptr) && (qShape->GetStorageShape().GetShapeSize() == 0)) {
223	        return true;
224	    }
225	
226	    auto attenoutShape = context->GetInputShape(ATTENTION_OUT_INDEX);
227	    if ((attenoutShape != nullptr) && (attenoutShape->GetStorageShape().GetShapeSize() == 0)) {
228	        return true;
229	    }
230	
231	    bool softmaxLseFlag = context->GetAttrs()->GetAttrPointer<bool>(SOFTMAX_LSE_FLAG_INDEX);
232	    if (softmaxLseFlag) {
233	        auto softmaxLseShape = context->GetInputShape(SOFTMAX_LSE_INDEX);
234	        if ((softmaxLseShape != nullptr) && (softmaxLseShape->GetStorageShape().GetShapeSize() == 0)) {
235	            return true;
236	        }
237	    }
238	
239	    uint32_t keyBIdx = 0;
240	    while ((context->GetDynamicInputShape(KEY_INDEX, keyBIdx)) != nullptr) {
241	        const gert::StorageShape *keyShape =
242	            const_cast<gert::StorageShape *>(context->GetDynamicInputShape(KEY_INDEX, keyBIdx));
243	        if (keyShape->GetShape().GetShapeSize() == 0) {
244	            return true;
245	        }
246	        keyBIdx++;
247	    }
248	
249	    uint32_t valueBIdx = 0;
250	    while ((context->GetDynamicInputShape(VALUE_INDEX, valueBIdx)) != nullptr) {
251	        const gert::StorageShape *valueShape =
252	            const_cast<gert::StorageShape *>(context->GetDynamicInputShape(VALUE_INDEX, valueBIdx));
253	        if (valueShape->GetShape().GetShapeSize() == 0) {
254	            return true;
255	        }
256	        valueBIdx++;
257	    }
258	
259	    return false;
260	}
261	
262	bool CheckGqaFeatureSupport(gert::TilingContext *context)
263	{
264	    auto pseShift = context->GetOptionalInputTensor(PSE_SHIFT_INDEX);
265	    auto queryPaddingSize = context->GetOptionalInputTensor(QUERY_PADDING_SIZE_INDEX);
266	    auto kvPaddingSize = context->GetOptionalInputTensor(KV_PADDING_SIZE_INDEX);
267	    auto quantScale2 = context->GetOptionalInputTensor(QUANT_SCALE2_INDEX);
268	    auto quantOffset2 = context->GetOptionalInputTensor(QUANT_OFFSET2_INDEX);
269	    if (pseShift != nullptr ||
270	        queryPaddingSize != nullptr ||
271	        kvPaddingSize != nullptr ||
272	        quantScale2 != nullptr ||
273	        quantOffset2 != nullptr) {
274	        return false;
275	    }
276	
277	    return true;
278	}
279	
280	bool CheckGqaConstrain(gert::TilingContext *context)
281	{
282	    if (CheckGqaInputLayoutSupport(context) &&
283	        CheckGqaDSupport(context) &&
284	        CheckGqaFeatureSupport(context)) {
285	            return true;
286	    }
287	    return false;
288	}
289	
290	bool isNotLegacyGQA(gert::TilingContext *context)
291	{
292	    const std::string inputLayoutStr = std::string(context->GetAttrs()->GetAttrPointer<char>(ATTR_INPUT_LAYOUT_INDEX));
293	    if (inputLayoutStr != "BSH" &&
294	        inputLayoutStr != "BSND" &&
295	        inputLayoutStr != "BNSD" &&
296	        inputLayoutStr != "BNSD_BSND" &&
297	        inputLayoutStr != "TND" &&
298	        inputLayoutStr != "NSD") {
299	        return true;
300	    }
301	
302	    auto queryRope = context->GetOptionalInputTensor(QUERY_ROPE_INDEX);
303	    auto keyRope = context->GetOptionalInputTensor(KEY_ROPE_INDEX);
304	    int64_t queryD = 0;
305	    int64_t queryRopeD = 0;
306	    int64_t valueD = 0;
307	    if (GetQkvD(context, queryD, queryRopeD, valueD) != true) {
308	        return false;
309	    }
310	
311	    if (queryD != valueD || queryRope != nullptr || keyRope != nullptr) {
312	        return true;
313	    }
314	
315	    if (inputLayoutStr == "TND" && valueD == HEAD_DIM_192) {
316	        return false;
317	    }
318	
319	    uint32_t keyDimNum = context->GetInputShape(KEY_INDEX)->GetShape().GetDimNum();
320	    uint32_t valueDimNum = context->GetInputShape(VALUE_INDEX)->GetShape().GetDimNum();
321	    if ((keyDimNum != DIM_NUM_3 && keyDimNum != DIM_NUM_4) ||
322	        (valueDimNum != DIM_NUM_3 && valueDimNum != DIM_NUM_4)) {
323	        return true;
324	    }
325	
326	    return false;
327	}
328	
329	bool CheckMlaInputLayoutSupport(const gert::TilingContext *context)
330	{
331	    const std::string inputLayoutStr = std::string(context->GetAttrs()->GetAttrPointer<char>(ATTR_INPUT_LAYOUT_INDEX));
332	    if (inputLayoutStr == "BSH" ||
333	        inputLayoutStr == "BNSD" ||
334	        inputLayoutStr == "BSND" ||
335	        inputLayoutStr == "BNSD_NBSD" ||
336	        inputLayoutStr == "BSND_NBSD" ||
337	        inputLayoutStr == "BSH_NBSD" ||
338	        inputLayoutStr == "TND" ||
339	        inputLayoutStr == "TND_NTD") {
340	        return true;
341	    }
342	
343	    return false;
344	}
345	
346	bool CheckMlaDSupport(gert::TilingContext *context)
347	{
348	    int64_t queryD = 0;
349	    int64_t queryRopeD = 0;
350	    int64_t valueD = 0;
351	    if (GetQkvD(context, queryD, queryRopeD, valueD) != true) {
352	        return false;
353	    }
354	
355	    if ((queryD  == 512 && queryRopeD  == 64 && valueD == 512)) { // 512: mla qkvD, 64: mla ropeD
356	        return true;
357	    }
358	
359	    return false;
360	}
361	
362	bool CheckMlaConstrain(gert::TilingContext *context)
363	{
364	    if (isNotLegacyGQA(context)) {
365	        return true;
366	    }
367	
368	    if (CheckMlaInputLayoutSupport(context) &&
369	        CheckMlaDSupport(context)) {
370	        return true;
371	    }
372	
373	    return false;
374	}
375	
376	bool RouteToFia(gert::TilingContext *context)
377	{
378	    if ((context == nullptr) || context->GetAttrs() == nullptr ||
379	    (context->GetInputDesc(QUERY_INDEX) == nullptr) ||
380	    (context->GetInputDesc(KEY_INDEX) == nullptr)) {
381	        return false;
382	    }
383	    auto platformInfoPtr = context->GetPlatformInfo();
384	    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
385	    if (ascendcPlatform.GetSocVersion() == platform_ascendc::SocVersion::ASCEND310P) {
386	        return false;
387	    }
388	
389	    ge::DataType qDataType = context->GetInputDesc(QUERY_INDEX)->GetDataType();
390	    ge::DataType kDataType = context->GetInputDesc(KEY_INDEX)->GetDataType();
391	    bool isRopeSplit = (context->GetOptionalInputTensor(QUERY_ROPE_INDEX) != nullptr &&
392	        context->GetOptionalInputTensor(KEY_ROPE_INDEX) != nullptr);
393	    if (isRopeSplit) {
394	        // MLA非量化
395	        if ((qDataType == ge::DT_FLOAT16 || qDataType == ge::DT_BF16) && (qDataType == kDataType)) {
396	            if (CheckGqaConstrain(context)) {
397	                OPS_LOG_I(context->GetNodeName(), "FIA RopeSplit GQA No quant.");
398	                return true;
399	            }
400	            if (CheckMlaConstrain(context)) {
401	                OPS_LOG_I(context->GetNodeName(), "FIA RopeSplit MLA No quant.");
402	                return true;
403	            }
404	            return false;
405	        }
406	    } else {
407	        // GQA非量化
408	        if ((qDataType == ge::DT_FLOAT16 || qDataType == ge::DT_BF16) && (qDataType == kDataType)) {
409	            OPS_LOG_I(context->GetNodeName(), "FIA GQA No quant.");
410	            return CheckGqaConstrain(context);
411	        }
412	    }
413	    return false;
414	}
415	} // namespace optiling

