11	/*!
12	 * \file fia_tiling_templates_registry.h
13	 * \brief
14	 */
15	
16	#ifndef FIA_TILING_TEMPLATES_REGISTRY_H
17	#define FIA_TILING_TEMPLATES_REGISTRY_H
18	
19	
20	#include <map>
21	#include <string>
22	#include <memory>
23	#include <exe_graph/runtime/tiling_context.h>
24	#include "fia_tiling_base.h"
25	#include "error/ops_error.h"
26	
27	namespace optiling {
28	
29	template <typename T> 
30	std::unique_ptr<FiaTilingBase> TILING_CLASS(gert::TilingContext *context)
31	{
32	    return std::unique_ptr<T>(new (std::nothrow) T(context));
33	}
34	
35	using FiaTilingClassCase = std::unique_ptr<FiaTilingBase> (*)(gert::TilingContext *);
36	
37	class FiaTilingCases {
38	public:
39	    explicit FiaTilingCases(std::string op_type) : op_type_(std::move(op_type))
40	    {
41	    }
42	
43	    template <typename T> 
44	    void AddTiling(int32_t priority)
45	    {
46	        OPS_CHECK(cases_.find(priority) != cases_.end(),
47	                   OPS_REPORT_VECTOR_INNER_ERR(op_type_, "There are duplicate registrations."), return);
48	        cases_[priority] = TILING_CLASS<T>;
49	        OPS_CHECK(
50	            cases_[priority] == nullptr,
51	            OPS_REPORT_VECTOR_INNER_ERR(op_type_, "Register op tiling func failed, please check the class name."),
52	            return);
53	    }
54	
55	    const std::map<int32_t, FiaTilingClassCase> &GetTilingCases()
56	    {
57	        return cases_;
58	    }
59	
60	private:
61	    std::map<int32_t, FiaTilingClassCase> cases_;
62	    const std::string op_type_;
63	};
64	
65	// --------------------------------Interfacce with soc version --------------------------------
66	class FiaTilingRegistry {
67	public:
68	    FiaTilingRegistry() = default;
69	
70	    static FiaTilingRegistry &GetInstance()
71	    {
72	        static FiaTilingRegistry registry_impl_;
73	        return registry_impl_;
74	    }
75	
76	    std::shared_ptr<FiaTilingCases> RegisterOp(const std::string &op_type,
77	                                            int32_t soc_version)
78	    {
79	        auto soc_iter = registry_map_.find(soc_version);
80	        if (soc_iter == registry_map_.end()) {
81	            std::map<std::string, std::shared_ptr<FiaTilingCases>> op_type_map;
82	            op_type_map[op_type] = std::shared_ptr<FiaTilingCases>(new (std::nothrow) FiaTilingCases(op_type));
83	            registry_map_[soc_version] = op_type_map;
84	        } else {
85	            if (soc_iter->second.find(op_type) == soc_iter->second.end()) {
86	                soc_iter->second[op_type] =
87	                    std::shared_ptr<FiaTilingCases>(new (std::nothrow) FiaTilingCases(op_type));
88	            }
89	        }
90	
91	        OPS_CHECK((registry_map_[soc_version][op_type] == nullptr), 
92	                    OPS_REPORT_VECTOR_INNER_ERR(op_type, "Register tiling func failed, please check the class name."), 
93	                    return nullptr);
94	        return registry_map_[soc_version][op_type];
95	    }
96	
97	    ge::graphStatus DoTilingImpl(gert::TilingContext *context, TilingInfo *tilingInfo)
98	    {
99	        int32_t soc_version = static_cast<int32_t>(platform_ascendc::SocVersion::RESERVED_VERSION);
100	        const char *op_type = context->GetNodeType();
101	        fe::PlatFormInfos *platformInfoPtr = context->GetPlatformInfo();
102	        if (platformInfoPtr == nullptr) {
103	            OPS_REPORT_VECTOR_INNER_ERR(op_type, "Do op tiling failed, platformInfoPtr is nullptr.");
104	            return ge::GRAPH_FAILED;
105	        }
106	        auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
107	        soc_version = static_cast<int32_t>(ascendcPlatform.GetSocVersion());
108	        OPS_LOG_I(context, "soc version is %d", soc_version);
109	        if (soc_version == static_cast<int32_t>(platform_ascendc::SocVersion::RESERVED_VERSION)) {
110	            OPS_REPORT_VECTOR_INNER_ERR(op_type, "Do op tiling failed, cannot find soc version.");
111	            return ge::GRAPH_FAILED;
112	        }
113	        auto tilingTemplateRegistryMap = GetTilingTemplates(op_type, soc_version);
114	        OPS_LOG_I(context, "op_type: %s", op_type);
115	        for (auto it = tilingTemplateRegistryMap.begin(); it != tilingTemplateRegistryMap.end(); ++it) {
116	            auto tilingTemplate = it->second(context);
117	            if (tilingTemplate != nullptr) {
118	                ge::graphStatus status = tilingTemplate->DoTiling(tilingInfo);
119	                if (status != ge::GRAPH_PARAM_INVALID) {
120	                    OPS_LOG_I(context, "Do general op tiling success priority=%d", it->first);
121	                    return status;
122	                }
123	                OPS_LOG_I(context, "Ignore general op tiling priority=%d", it->first);
124	            }
125	        }
126	        OPS_REPORT_VECTOR_INNER_ERR(op_type, "Do op tiling failed, no valid template is found.");
127	        return ge::GRAPH_FAILED;
128	    }
129	
130	    const std::map<int32_t, FiaTilingClassCase> &GetTilingTemplates(const std::string &op_type,
131	                                                                    int32_t soc_version)
132	    {
133	        auto soc_iter = registry_map_.find(soc_version);
134	        OPS_CHECK(soc_iter == registry_map_.end(),
135	                    OPS_REPORT_VECTOR_INNER_ERR(op_type, "Get op tiling func failed, please check the soc version %d",
136	                                                soc_version),
137	                    return empty_tiling_case_);
138	        auto op_iter = soc_iter->second.find(op_type);
139	        OPS_CHECK(op_iter == soc_iter->second.end(),
140	                    OPS_REPORT_VECTOR_INNER_ERR(op_type, "Get op tiling func failed, please check the op name."),
141	                    return empty_tiling_case_);
142	        return op_iter->second->GetTilingCases();
143	    }
144	
145	private:
146	    std::map<int32_t, std::map<std::string, std::shared_ptr<FiaTilingCases>>> registry_map_; // key is socversion
147	    const std::map<int32_t, FiaTilingClassCase> empty_tiling_case_{};
148	};
149	
150	class FiaRegister {
151	public:
152	    explicit FiaRegister(std::string op_type) : op_type_(std::move(op_type))
153	    {
154	    }
155	
156	    template <typename T> 
157	    FiaRegister &tiling(int32_t priority, int32_t soc_version)
158	    {
159	        auto tilingCases = FiaTilingRegistry::GetInstance().RegisterOp(op_type_, soc_version);
160	        OPS_CHECK((tilingCases == nullptr),
161	                    OPS_REPORT_VECTOR_INNER_ERR(op_type_, "Register op tiling failed, please the op name."),
162	                    return *this);
163	        tilingCases->AddTiling<T>(priority);
164	        return *this;
165	    }
166	
167	    template <typename T> 
168	    FiaRegister &tiling(int32_t priority, const std::vector<int32_t>& soc_versions)
169	    {
170	        for (int32_t soc_version : soc_versions) {
171	            auto tilingCases = FiaTilingRegistry::GetInstance().RegisterOp(op_type_, soc_version);
172	            OPS_CHECK(tilingCases == nullptr,
173	                    OPS_REPORT_VECTOR_INNER_ERR(op_type_, "Register op tiling failed, please the op name."),
174	                    return *this);
175	            tilingCases->AddTiling<T>(priority);
176	        }
177	        return *this;
178	    }
179	
180	private:
181	    const std::string op_type_;
182	};
183	
184	// op_type: 算子名称， class_name: 注册的 tiling 类, soc_version：芯片版本号
185	// priority: tiling 类的优先级, 越小表示优先级越高, 即会优先选择这个tiling类
186	#define REGISTER_TILING_TEMPLATE_FIA(op_type, class_name, soc_versions, priority) \
187	        static FiaRegister VAR_UNUSED##op_type##class_name##priority_register = \
188	                FiaRegister(#op_type).tiling<class_name>(priority, soc_versions)
189	} // namespace optiling
190	
191	#endif

