enum class FIA_LAYOUT : uint32_t {
    BSH = 0,
    BSND = 0,
    BNSD = 1,
    NZ = 2,
    TND = 3,
    NBSD = 4,
    NTD = 5
};

template <typename Q_T,
          typename KV_T,
          typename OUT_T,
          typename ORIGIN_T,
          const bool PAGE_ATTENTION = false,
          const bool FLASH_DECODE = false,
          FIA_LAYOUT LAYOUT_T = FIA_LAYOUT::BSH,
          const uint8_t ANTIQUANT_MODE = 0,
          const bool SHARED_PREFIX = false,
          FIA_LAYOUT KV_LAYOUT_T = FIA_LAYOUT::BSH,
          const bool SOFTMAX_WITH_BRC = false,
          typename... Args>
struct FIAType {
    using queryType = Q_T;
    using kvType = KV_T;
    using outputType = OUT_T;
    using orginalType = ORIGIN_T;
    static constexpr bool pageAttention = PAGE_ATTENTION;
    static constexpr bool flashDecode = FLASH_DECODE;
    static constexpr FIA_LAYOUT layout = LAYOUT_T;
    static constexpr uint8_t antiquantMode = ANTIQUANT_MODE;
    static constexpr bool sharedPrefix = SHARED_PREFIX;
    static constexpr FIA_LAYOUT kvLayout = KV_LAYOUT_T;
    static constexpr bool softmaxWithBrc = SOFTMAX_WITH_BRC;
};

